<?php include "auth.php"; include "../database.php"; if($_SERVER['REQUEST_METHOD']==='POST'){$pid=intval($_POST['partner_id']);$t=trim($_POST['title']);$d=trim($_POST['description']);$sd=$_POST['start_date'];$ed=$_POST['end_date'];$s=$conn->prepare("INSERT INTO advertisement(partner_id,title,description,start_date,end_date,status) VALUES(?,?,?,?,?,'Active')");$s->bind_param("issss",$pid,$t,$d,$sd,$ed);$s->execute();header("Location: ads.php");exit;}if(isset($_GET['delete'])){$id=intval($_GET['delete']);$s=$conn->prepare("DELETE FROM advertisement WHERE ad_id=?");$s->bind_param("i",$id);$s->execute();header("Location: ads.php");exit;}$partners=$conn->query("SELECT partner_id,partner_name FROM partner WHERE status='Active' ORDER BY partner_name");$r=$conn->query("SELECT a.*,p.partner_name FROM advertisement a JOIN partner p ON a.partner_id=p.partner_id ORDER BY a.ad_id DESC"); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Advertisements</title><link rel="stylesheet" href="../style.css"></head><body><main class="container"><h1>Advertisement Management</h1><a class="btn secondary" href="index.php">Dashboard</a><div class="form-box"><form method="POST"><select name="partner_id" required><option value="">Select partner</option><?php while($p=$partners->fetch_assoc()):?><option value="<?=$p['partner_id']?>"><?=htmlspecialchars($p['partner_name'])?></option><?php endwhile;?></select><input name="title" placeholder="Ad title" required><textarea name="description" placeholder="Description"></textarea><label>Start date</label><input type="date" name="start_date" required><label>End date</label><input type="date" name="end_date" required><button>Add Advertisement</button></form></div><table><tr><th>Title</th><th>Partner</th><th>Dates</th><th>Action</th></tr><?php while($a=$r->fetch_assoc()):?><tr><td><?=htmlspecialchars($a['title'])?></td><td><?=htmlspecialchars($a['partner_name'])?></td><td><?=$a['start_date']?> to <?=$a['end_date']?></td><td><a class="btn secondary" href="?delete=<?=$a['ad_id']?>" onclick="return confirm('Delete this advertisement?')">Delete</a></td></tr><?php endwhile;?></table></main></body></html>